import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import SsoOptions from './SsoOptions';

const LoginForm = () => {
    const navigate = useNavigate();

    const [formData, setFormData] = useState({
        email: '',
        password: ''
    });

    const [errors, setErrors] = useState({});
    const [showPassword, setShowPassword] = useState(false);

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: value
        }));

        // Clear error when user types
        if (errors[name]) {
            setErrors(prev => ({
                ...prev,
                [name]: undefined
            }));
        }
    };

    const handleKeyDown = (e) => {
        if (e.key === " ") {
            e.preventDefault();
        }
    };

    const handleSubmit = (e) => {
        e.preventDefault();

        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        const { email, password } = formData;
        const newErrors = {};
        let isValid = true;

        if (!emailRegex.test(email) || email === "") {
            newErrors.email = "Please enter a valid email address";
            isValid = false;
        }

        if (password.length < 6 || password === "") {
            newErrors.password = "Password must be at least 6 characters long";
            isValid = false;
        }

        setErrors(newErrors);

        if (!isValid) {
            return;
        }

        const storedUser = localStorage.getItem('user');
        if (storedUser) {
            const userData = JSON.parse(storedUser);
            if (userData.email === email && userData.password === password) {
                // Reset form
                setFormData({
                    email: '',
                    password: ''
                });
                setErrors({});

                navigate('/dashboard');
                return;
            }
            if(userData.email === email && userData.password !== password ){
                setErrors({
                    email: 'Email is already registered',
                    password: ' Password does not match'
                });
                return;
            }
        }

        alert("Invalid login details");
        // Reset form
        setFormData({
            email: '',
            password: ''
        });
        setErrors({});
    };

    return (
        <div className="w-full flex flex-col gap-1">
            <div className="bg-surface-container-lowest border border-outline-variant rounded-lg p-5 md:p-6 shadow-sm">
                <div className="text-center mb-4">
                    <h1 className="font-headline-lg text-headline-lg text-primary mb-2">Welcome Back</h1>
                    <p className="font-body-md text-body-md text-on-surface-variant">Access your secure dashboard</p>
                </div>
                <form className="space-y-4" onSubmit={handleSubmit}>
            {/* Email Field */}
            <div className="flex flex-col">
                <label className="font-label-md text-label-md text-on-surface-variant" htmlFor="email">Email</label>
                <div className="relative">
                    <span className="material-symbols-outlined absolute left-3 top-1/2 -translate-y-1/2 text-on-surface-variant text-[20px]" data-icon="mail">mail</span>
                    <input 
                        className={`w-full h-10 pl-10 pr-3 bg-surface rounded border ${errors.email ? 'border-error focus:border-error focus:ring-error/20' : 'border-outline focus:border-secondary focus:ring-secondary/20'} focus:outline-none focus:ring-2 transition-all font-body-md text-body-md text-on-surface placeholder:text-on-surface-variant/50`} 
                        id="email" 
                        name="email" 
                        placeholder="name@company.com"  
                        type="email" 
                        onChange={handleChange} 
                        value={formData.email} 
                    />
                </div>
                {errors.email && <p className="text-error text-xs mt-1">{errors.email}</p>}
            </div>

            {/* Password Field */}
            <div className="flex flex-col">
                <div className="flex justify-between items-center">
                    <label className="font-label-md text-label-md text-on-surface-variant" htmlFor="password">Password</label>
                    <Link className="font-label-sm text-label-sm text-secondary hover:underline transition-all" to="/forget-password">Forgot Password?</Link>
                </div>
                <div className="relative">
                    <input 
                        className={`w-full h-10 pl-4 pr-10 bg-surface rounded border ${errors.password ? 'border-error focus:border-error focus:ring-error/20' : 'border-outline focus:border-secondary focus:ring-secondary/20'} focus:outline-none focus:ring-2 transition-all font-body-md text-body-md text-on-surface placeholder:text-on-surface-variant/50`} 
                        id="password" 
                        name="password"
                        placeholder="••••••••" 
                        type={showPassword ? "text" : "password"} 
                        onChange={handleChange} 
                        value={formData.password}
                        onKeyDown={handleKeyDown}
                    />
                    <span 
                        className="material-symbols-outlined absolute right-3 top-1/2 -translate-y-1/2 text-on-surface-variant cursor-pointer hover:text-on-surface text-[20px]" 
                        onClick={() => setShowPassword(!showPassword)}
                    >
                        {showPassword ? 'visibility' : 'visibility_off'}
                    </span>
                </div>
                {errors.password && <p className="text-error text-xs mt-1">{errors.password}</p>}
            </div>

            {/* CTA Button */}
            <div className="pt-2">
                <button className="w-full h-12 bg-secondary text-white font-label-md text-label-md rounded-lg shadow-[0px_4px_6px_rgba(0,0,0,0.05)] hover:bg-primary-container active:scale-[0.98] transition-all flex items-center justify-center gap-2" type="submit">
                    <span>Log In</span>
                    <span className="material-symbols-outlined text-[18px]">login</span>
                </button>
            </div>

            <SsoOptions />
                </form>
            </div>

            {/* Footer Link */}
            <div className="text-center mt-2">
                <p className="font-body-sm text-body-sm text-on-surface-variant">
                    Don't have an account? 
                    <Link to="/signup" className="text-secondary font-semibold hover:underline"> Sign Up</Link>
                </p>
            </div>
        </div>
    );
};

export default LoginForm;
